523:       ctx.beginPath(); ctx.ellipse(px + 16, py + 26, 12, 5, 0, 0, TAU); ctx.fill();
524:       if (type === 'geladeira') {
525:         ctx.fillStyle = c.searched ? '#7c7e78' : '#b8bcb4'; ctx.fillRect(px + 7, py + 2, 18, 28);
526:         ctx.fillStyle = '#8f938b'; ctx.fillRect(px + 8, py + 13, 16, 2);
527:         ctx.fillStyle = '#5f625b'; ctx.fillRect(px + 21, py + 7, 2, 5);
528:       } else if (type === 'farmacia') {
529:         ctx.fillStyle = '#d5d7cf'; ctx.fillRect(px + 5, py + 4, 22, 24);
530:         ctx.fillStyle = '#9aa096'; ctx.fillRect(px + 6, py + 15, 20, 2);
531:         ctx.fillStyle = '#b6423b'; ctx.fillRect(px + 14, py + 8, 4, 10); ctx.fillRect(px + 11, py + 11, 10, 4);
532:       } else if (type === 'mercado') {
533:         ctx.fillStyle = '#5a4a33'; ctx.fillRect(px + 2, py + 5, 28, 20);
534:         ctx.fillStyle = '#6d5b3f'; ctx.fillRect(px + 2, py + 5, 28, 4);
535:         for (let i = 0; i < 3; i++) {
536:           ctx.fillStyle = ['#b7a15c', '#8e6a46', '#6f8648'][i];
537:           ctx.fillRect(px + 5 + i * 8, py + 11, 5, 8);
538:         }
539:       } else if (type === 'quartel' || type === 'armario_militar' || type === 'caixa_suprimentos') {
540:         ctx.fillStyle = type === 'caixa_suprimentos' ? '#5c6b45' : '#4f5a3d';
541:         ctx.fillRect(px + 4, py + 5, 24, 23);
542:         ctx.fillStyle = '#6c7a52'; ctx.fillRect(px + 4, py + 5, 24, 4);
543:         ctx.strokeStyle = '#333b26'; ctx.lineWidth = 1; ctx.strokeRect(px + 4, py + 5, 24, 23);
544:         ctx.fillStyle = '#c9ccb4'; ctx.fillRect(px + 14, py + 16, 4, 4);
545:       } else if (type === 'oficina' || type === 'ferramentas' || type === 'caixa' || type === 'fazenda') {
546:         ctx.fillStyle = type === 'fazenda' ? '#7a6238' : '#664f32';
547:         ctx.fillRect(px + 4, py + 7, 24, 21);
548:         ctx.fillStyle = 'rgba(190,160,100,0.35)'; ctx.fillRect(px + 4, py + 7, 24, 4);
549:         ctx.strokeStyle = '#3c2e1b'; ctx.lineWidth = 1; ctx.strokeRect(px + 4, py + 7, 24, 21);
550:         ctx.beginPath(); ctx.moveTo(px + 4, py + 18); ctx.lineTo(px + 28, py + 18); ctx.stroke();
551:       } else {
552:         ctx.fillStyle = '#6d5b40'; ctx.fillRect(px + 5, py + 6, 22, 22);
553:         ctx.fillStyle = 'rgba(210,190,150,0.25)'; ctx.fillRect(px + 5, py + 6, 22, 4);
554:       }
555:       ctx.restore();
556:       // brilho de vasculhável não saqueado
557:       if (!c.searched && c.items.length) {
558:         const pulse = 0.3 + Math.sin(this.time * 2 + c.x) * 0.12;
559:         ctx.strokeStyle = `rgba(230,210,140,${pulse})`;
560:         ctx.lineWidth = 1.5;
561:         ctx.strokeRect(px + 3, py + 3, TILE - 6, TILE - 6);
562:       }
563:     }
564:   }
