635:   drawVehicle(ctx, v) {
636:     const night = isNight(this.game.time);
637:     ctx.save();
638:     ctx.translate(v.x, v.y);
639:     ctx.rotate(v.angle);
640:     // sombra
641:     ctx.fillStyle = 'rgba(0,0,0,0.38)';
642:     ctx.beginPath(); ctx.ellipse(0, 6, v.w / 2 + 2, v.h / 2 + 2, 0, 0, TAU); ctx.fill();
643:     // rodas
644:     ctx.fillStyle = '#1c1c1c';
645:     const wx = v.w * 0.3, wy = v.h / 2 - 2;
646:     ctx.fillRect(-wx - 5, -wy - 3, 10, 6); ctx.fillRect(wx - 5, -wy - 3, 10, 6);
647:     ctx.fillRect(-wx - 5, wy - 3, 10, 6); ctx.fillRect(wx - 5, wy - 3, 10, 6);
648:     // corpo
649:     ctx.fillStyle = v.color;
650:     this.roundRect(ctx, -v.w / 2, -v.h / 2, v.w, v.h, 6); ctx.fill();
651:     ctx.fillStyle = 'rgba(255,255,255,0.12)';
652:     this.roundRect(ctx, -v.w / 2 + 4, -v.h / 2 + 3, v.w - 8, v.h * 0.3, 4); ctx.fill();
653:     // cabine / vidros
654:     ctx.fillStyle = '#25333a';
655:     const cabW = v.w * 0.38;
656:     this.roundRect(ctx, -cabW / 2 + v.w * 0.1, -v.h / 2 + 3, cabW, v.h - 6, 3); ctx.fill();
657:     ctx.fillStyle = 'rgba(150,200,210,0.3)';
658:     ctx.fillRect(-cabW / 2 + v.w * 0.1 + 2, -v.h / 2 + 5, cabW - 4, 3);
659:     // faróis
660:     const lightsOn = v.occupied && v.engineOn;
661:     ctx.fillStyle = lightsOn ? '#ffe7a3' : '#7d7a64';
662:     ctx.fillRect(v.w / 2 - 4, -v.h / 2 + 3, 4, 5);
663:     ctx.fillRect(v.w / 2 - 4, v.h / 2 - 8, 4, 5);
664:     ctx.fillStyle = '#8f2f2a';
665:     ctx.fillRect(-v.w / 2, -v.h / 2 + 3, 3, 5);
666:     ctx.fillRect(-v.w / 2, v.h / 2 - 8, 3, 5);
667:     // ferrugem / dano
668:     if (v.condition < 55) {
669:       ctx.fillStyle = 'rgba(90,50,25,0.55)';
670:       ctx.fillRect(-v.w * 0.2, -v.h / 2 + 2, 5, 5);
671:       ctx.fillRect(v.w * 0.15, v.h / 2 - 6, 7, 4);
672:     }
673:     ctx.restore();
674:     if (night && v.occupied && v.engineOn) {
675:       // cone dos faróis
676:       ctx.save();
677:       ctx.translate(v.x, v.y); ctx.rotate(v.angle);
678:       const grad = ctx.createLinearGradient(v.w / 2, 0, v.w / 2 + 200, 0);
679:       grad.addColorStop(0, 'rgba(255,240,180,0.22)');
680:       grad.addColorStop(1, 'rgba(255,240,180,0)');
681:       ctx.fillStyle = grad;
682:       ctx.beginPath(); ctx.moveTo(v.w / 2, -6); ctx.lineTo(v.w / 2 + 220, -90); ctx.lineTo(v.w / 2 + 220, 90); ctx.lineTo(v.w / 2, 6); ctx.closePath(); ctx.fill();
683:       ctx.restore();
684:     }
685:     if (v.occupied) {
686:       ctx.fillStyle = 'rgba(210,230,190,0.8)';
687:       ctx.font = '9px system-ui';
688:       ctx.textAlign = 'center';
689:       ctx.fillText(`⛽ ${Math.round(v.fuel)}% • 🔧 ${Math.round(v.condition)}%`, v.x, v.y - v.h / 2 - 8);
690:     }
691:   }
692: 
693:   roundRect(ctx, x, y, w, h, r) {
694:     ctx.beginPath();
695:     ctx.moveTo(x + r, y);
696:     ctx.arcTo(x + w, y, x + w, y + h, r);
697:     ctx.arcTo(x + w, y + h, x, y + h, r);
698:     ctx.arcTo(x, y + h, x, y, r);
699:     ctx.arcTo(x, y, x + w, y, r);
700:     ctx.closePath();
701:   }
