703:   // ================= PERSONAGENS =================
704:   drawTreeCanopies(ctx, minX, maxX, minY, maxY) {
705:     const g = this.game;
706:     const winter = g.seasonIndex === 2;
707:     const autumn = g.seasonIndex === 1;
708:     const t = this.time;
709:     for (const tr of g.world.trees) {
710:       const tx = tr.x / TILE, ty = tr.y / TILE;
711:       if (tx < minX - 1.5 || tx > maxX + 1.5 || ty < minY - 1.5 || ty > maxY + 1.5) continue;
712:       const sway = Math.sin(t * 0.9 + tr.sway) * 1.2;
713:       const r = tr.r * 8;
714:       ctx.fillStyle = 'rgba(0,0,0,0.28)';
715:       ctx.beginPath(); ctx.ellipse(tr.x + 3, tr.y + 5, r * 0.9, r * 0.5, 0, 0, TAU); ctx.fill();
716:       // tronco
717:       ctx.fillStyle = '#43331f';
718:       ctx.fillRect(tr.x - 2, tr.y + 1, 4, 8);
719:       const base = winter ? ['#33413a', '#3c4b43', '#2a3730'] : autumn ? ['#6b5a2a', '#7a6330', '#5b4c24'] : ['#2e4a2c', '#3a5933', '#233a22'];
720:       ctx.fillStyle = base[tr.variant % 3];
721:       ctx.beginPath(); ctx.arc(tr.x - r * 0.35 + sway, tr.y - 2, r * 0.62, 0, TAU); ctx.fill();
722:       ctx.fillStyle = base[(tr.variant + 1) % 3];
723:       ctx.beginPath(); ctx.arc(tr.x + r * 0.3 + sway, tr.y - 4, r * 0.58, 0, TAU); ctx.fill();
724:       ctx.fillStyle = base[(tr.variant + 2) % 3];
725:       ctx.beginPath(); ctx.arc(tr.x + sway, tr.y - r * 0.4, r * 0.66, 0, TAU); ctx.fill();
726:       // highlight
727:       ctx.fillStyle = winter ? 'rgba(210,225,230,0.08)' : 'rgba(150,190,110,0.12)';
728:       ctx.beginPath(); ctx.arc(tr.x - r * 0.2 + sway, tr.y - r * 0.5, r * 0.4, 0, TAU); ctx.fill();
729:     }
730:     // pedras
731:     for (const rock of g.world.rocks) {
732:       if (rock.x / TILE < minX - 1 || rock.x / TILE > maxX + 1 || rock.y / TILE < minY - 1 || rock.y / TILE > maxY + 1) continue;
733:       const r = rock.r * 13;
734:       ctx.fillStyle = 'rgba(0,0,0,0.28)'; ctx.beginPath(); ctx.ellipse(rock.x + 2, rock.y + 3, r, r * 0.55, 0, 0, TAU); ctx.fill();
735:       ctx.fillStyle = '#5b5b52'; ctx.beginPath(); ctx.ellipse(rock.x, rock.y, r, r * 0.75, 0.4, 0, TAU); ctx.fill();
736:       ctx.fillStyle = '#6d6d63'; ctx.beginPath(); ctx.ellipse(rock.x - r * 0.2, rock.y - r * 0.25, r * 0.55, r * 0.4, 0.4, 0, TAU); ctx.fill();
737:     }
738:   }
739:   drawPlayer(ctx) {
740:     const g = this.game, p = g.player;
741:     if (p.inVehicle) {
742:       // pequeno indicador de motorista
743:       const v = p.inVehicle;
744:       ctx.fillStyle = 'rgba(220,235,200,0.85)';
745:       ctx.beginPath(); ctx.arc(v.x + Math.cos(v.angle) * 6, v.y + Math.sin(v.angle) * 6, 4, 0, TAU); ctx.fill();
746:       return;
747:     }
748:     if (p.downed) {
749:       this.drawSurvivor(ctx, p.x, p.y, p.angle, '#5d6b57', '#b58a6b', 0, false, { downed: true, name: p.name, player: true });
750:       return;
751:     }
752:     const moving = g.input.up || g.input.down || g.input.left || g.input.right;
753:     const bob = moving ? Math.sin(g.clock * 12) * 2 : Math.sin(g.clock * 2) * 0.5;
754:     this.drawSurvivor(ctx, p.x, p.y, p.angle, '#556b52', '#c99a78', bob, moving, { player: true, weapon: g.weaponStack, swing: p.swing, flashlight: p.flashlight });
755:     if (p.bleed > 20) {
756:       ctx.fillStyle = 'rgba(120,20,18,0.35)';
757:       ctx.beginPath(); ctx.arc(p.x + 3, p.y + 5, 9, 0, TAU); ctx.fill();
758:     }
759:   }
760:   drawSurvivor(ctx, x, y, angle, jacket, skin, bob, moving, opts = {}) {
761:     ctx.save();
762:     ctx.translate(x, y);
763:     // sombra
764:     ctx.fillStyle = 'rgba(0,0,0,0.35)';
765:     ctx.beginPath(); ctx.ellipse(0, 5, 10, 5, 0, 0, TAU); ctx.fill();
766:     ctx.rotate(angle);
767:     const downed = opts.downed;
768:     if (downed) {
769:       ctx.fillStyle = jacket;
770:       ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, TAU); ctx.fill();
771:       ctx.fillStyle = skin;
772:       ctx.beginPath(); ctx.arc(10, 0, 5, 0, TAU); ctx.fill();
773:       ctx.restore();
774:       return;
775:     }
776:     // pernas
777:     const legSwing = moving ? Math.sin(this.game.clock * 12) * 4 : 0;
778:     ctx.strokeStyle = '#383d34'; ctx.lineWidth = 3;
779:     ctx.beginPath(); ctx.moveTo(-3, -3); ctx.lineTo(-6 + legSwing, -7); ctx.stroke();
780:     ctx.beginPath(); ctx.moveTo(-3, 3); ctx.lineTo(-6 - legSwing, 7); ctx.stroke();
781:     // mochila
782:     if (opts.player) {
783:       ctx.fillStyle = '#4e4232';
784:       this.roundRect(ctx, -10, -6, 6, 12, 2); ctx.fill();
785:     }
786:     // corpo
787:     ctx.fillStyle = jacket;
788:     this.roundRect(ctx, -6, -6 + bob * 0.2, 14, 12, 5); ctx.fill();
789:     ctx.fillStyle = 'rgba(255,255,255,0.08)';
790:     this.roundRect(ctx, -4, -5, 9, 3, 1.5); ctx.fill();
791:     // braços
792:     const armSwing = opts.swing ? Math.sin((1 - opts.swing) * Math.PI) * 0.7 : 0;
793:     ctx.strokeStyle = jacket; ctx.lineWidth = 3.4;
794:     ctx.beginPath(); ctx.moveTo(3, -5); ctx.lineTo(7 + Math.cos(armSwing) * 4, -7); ctx.stroke();
795:     ctx.beginPath(); ctx.moveTo(3, 5); ctx.lineTo(7, 7 + armSwing * 3); ctx.stroke();
796:     // mãos
797:     ctx.fillStyle = skin;
798:     ctx.beginPath(); ctx.arc(8, -7, 2.2, 0, TAU); ctx.fill();
799:     ctx.beginPath(); ctx.arc(8, 7 + armSwing * 3, 2.2, 0, TAU); ctx.fill();
800:     // cabeça
801:     ctx.fillStyle = skin;
802:     ctx.beginPath(); ctx.arc(4, 0, 5.3, 0, TAU); ctx.fill();
803:     ctx.fillStyle = '#2b2620';
804:     ctx.beginPath(); ctx.arc(3, 0, 5.3, Math.PI * 0.7, Math.PI * 1.3); ctx.fill();
805:     // arma
806:     if (opts.weapon) {
807:       const def = ITEMS[opts.weapon.id];
808:       if (def?.gun) {
809:         ctx.fillStyle = '#2e3235';
810:         ctx.fillRect(8, -2, 14, 3);
811:         ctx.fillStyle = '#4d5458';
812:         ctx.fillRect(10, -3, 7, 2);
813:       } else if (def?.weapon) {
814:         ctx.strokeStyle = '#9a9a8e'; ctx.lineWidth = 2;
815:         ctx.beginPath(); ctx.moveTo(6, 6); ctx.lineTo(18, 8); ctx.stroke();
816:         ctx.fillStyle = '#7a5a33'; ctx.fillRect(5, 5, 4, 4);
817:       }
818:       if (opts.swing) {
819:         ctx.strokeStyle = `rgba(235,235,215,${opts.swing * 0.4})`;
820:         ctx.lineWidth = 2;
821:         ctx.beginPath(); ctx.arc(0, 0, def?.range ? Math.min(24, def.range * 0.5) : 20, -0.9, 0.9); ctx.stroke();
822:       }
823:     }
824:     if (opts.flashlight) {
825:       ctx.fillStyle = '#d8d6b0';
826:       ctx.fillRect(7, -8, 4, 3);
827:     }
828:     ctx.restore();
829:     if (opts.name) {
830:       ctx.fillStyle = 'rgba(225,235,215,0.85)';
831:       ctx.font = '600 10px system-ui';
832:       ctx.textAlign = 'center';
833:       ctx.fillText(opts.name, x, y - 22);
834:     }
835:   }
836:   drawZombies(ctx, minX, maxX, minY, maxY) {
837:     const g = this.game;
838:     for (const z of g.zombies) {
839:       const tx = z.x / TILE, ty = z.y / TILE;
840:       if (tx < minX - 1 || tx > maxX + 1 || ty < minY - 1 || ty > maxY + 1) continue;
841:       const def = ZOMBIE_TYPES[z.type] || ZOMBIE_TYPES.comum;
842:       const s = z.size;
843:       const lunge = (z.lunge || 0) * 3;
844:       ctx.save();
845:       ctx.translate(z.x, z.y);
846:       ctx.fillStyle = 'rgba(0,0,0,0.4)';
847:       ctx.beginPath(); ctx.ellipse(0, 6, 10 * s, 5 * s, 0, 0, TAU); ctx.fill();
848:       ctx.rotate(z.angle);
849:       if (z.hitFlash > 0) ctx.globalAlpha = 1;
850:       const bob = Math.sin(z.anim * 4) * 1.4;
851:       if (z.type === 'rastejante') {
852:         ctx.fillStyle = z.hitFlash > 0.3 ? '#e8e0d2' : '#4c5940';
853:         ctx.beginPath(); ctx.ellipse(-2, 0, 13 * s, 6 * s, 0, 0, TAU); ctx.fill();
854:         ctx.fillStyle = z.hitFlash > 0.3 ? '#f0e8dc' : '#7c8a62';
855:         ctx.beginPath(); ctx.arc(10 * s, -1, 5 * s, 0, TAU); ctx.fill();
856:         ctx.strokeStyle = '#4c5940'; ctx.lineWidth = 3 * s;
857:         ctx.beginPath(); ctx.moveTo(4, -4); ctx.lineTo(14 + lunge, -8); ctx.stroke();
858:         ctx.beginPath(); ctx.moveTo(4, 4); ctx.lineTo(14 + lunge, 8); ctx.stroke();
859:       } else {
860:         // pernas
861:         ctx.strokeStyle = '#3a4034'; ctx.lineWidth = 3 * s;
862:         const legSwing = Math.sin(z.anim * 6) * 4 * s;
863:         ctx.beginPath(); ctx.moveTo(-4, -4); ctx.lineTo(-8 + legSwing, -8); ctx.stroke();
864:         ctx.beginPath(); ctx.moveTo(-4, 4); ctx.lineTo(-8 - legSwing, 8); ctx.stroke();
865:         // corpo
866:         ctx.fillStyle = z.hitFlash > 0.3 ? '#e8e0d2' : def.skin;
867:         this.roundRect(ctx, -7 * s, -6 * s + bob, 15 * s, 12 * s, 5 * s); ctx.fill();
868:         ctx.fillStyle = 'rgba(30,40,20,0.28)';
869:         this.roundRect(ctx, -5 * s, 1 * s, 9 * s, 4 * s, 2 * s); ctx.fill();
