  ui.refreshSaveInfo();
}

function attachGame(g, { multiplayer = false } = {}) {
  game = g;
  g.ui = ui;
  g.mp = multiplayer ? mp : null;
  g.isHost = !g.mp || g.mp.isHost !== false;

